function distance(nums) {
  const groups = new Map();
  for (let i = 0; i < nums.length; i++) {
    if (!groups.has(nums[i])) groups.set(nums[i], []);
    groups.get(nums[i]).push(i);
  }

  const result = new Array(nums.length).fill(0);
  for (const indices of groups.values()) {
    let total = 0;
    for (const index of indices) total += index;
    let prefix = 0;
    for (let k = 0; k < indices.length; k++) {
      const index = indices[k];
      const leftSum = index * k - prefix;
      const rightSum = (total - prefix - index) - index * (indices.length - 1 - k);
      result[index] = leftSum + rightSum;
      prefix += index;
    }
  }
  return result;
}

