function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 10);
    const top = [0, 1, 3, 6, 1000000000][pick(0, 4)];
    return [Array.from({ length: n }, () => pick(0, top))];
  }
  const n = 2000;
  const style = pick(0, 2);
  if (style === 0) return [new Array(n).fill(pick(0, 1000000000))];
  if (style === 1) {
    const values = Array.from({ length: pick(2, 40) }, () => pick(0, 1000000000));
    return [Array.from({ length: n }, () => values[pick(0, values.length - 1)])];
  }
  return [Array.from({ length: n }, () => pick(0, 3000))];
}
